-- public.craft_units_held(p_world uuid, p_uid uuid, p_recipe text, p_prefer bigint)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.craft_units_held(p_world uuid, p_uid uuid, p_recipe text, p_prefer bigint)
 RETURNS integer[]
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v int[] := rarity_tally(); r record;
begin
  for r in
    select rarity_step(it.rare) as step, sum(st.count)::int as n
      from craft_stock(p_world, p_uid, p_prefer) st join item it on it.id = st.id
     where st.def in (select ri.item from recipe_input ri
                       where ri.recipe = p_recipe and not exists (select 1 from vessel_def v where v.item = ri.item))
     group by 1
  loop
    v[r.step] := r.n;
  end loop;
  return v;
end $function$
